/**
 * Returns current node prefix
 * @return {string} prefix
 */
__gptDialog_getNodePrefix = function () {
    var separator = "-";
    var currentId = context.currentNode.id.split(separator);

    return currentId.length > 1
        ? currentId.slice(0, -1).join(separator) + separator
        : "";
};

/**
 * Makes a local goto destination nodeId including prefix
 * @param {string} nodeId
 * @return {string} full nodeId
 */
__gptDialog_makeLocalNodeId = function (nodeId) {
    if (global.hasOwnProperty("__gptDialogComponentIdPrefix") && __gptDialogComponentIdPrefix != null)
        return __gptDialogComponentIdPrefix + nodeId;

    if (!context.currentNode.id)
        return nodeId;

    var separator = "-";
    var output = context.currentNode.id.split(separator);

    output[output.length - 1] = nodeId;
    return output.join(separator);
};

__gptDialogComponentIdPrefix = __gptDialog_getNodePrefix();
__gptDialogVADEnabled = __persona.allowBargeIn;
__gptSkipVAD = false;

__gptDialog_onVoiceDetected = function () {
    var destination = __gptDialog_makeLocalNodeId(__gptDialogBargeInNodeId);

    if (__logPrompt)
        log_debug("VAD detected! Processing in node ID: " + destination);

    goto(destination); /* because of concurrent JS execution !! */
    stopVoiceDetection();
    stopPlayingAudio();
}

__gptDialog_getSimplifiedHistory = function (maxRows = null) {
    var msgHistory = '';
    var prevMsgs = __gptDialog_getPrevMessages();
    var _fromPos = 0;

    if (maxRows != null && prevMsgs.length > maxRows) {
        _fromPos = prevMsgs.length - maxRows;
    }

    for (var i = _fromPos; i < prevMsgs.length; i++) {
        if (prevMsgs[i].role == 'assistant' && prevMsgs[i].content) {
            msgHistory += "Assistant: " + prevMsgs[i].content + "\n";
        } else if (prevMsgs[i].role == 'user') {
            msgHistory += "User: " + prevMsgs[i].content + "\n";
        }
    }
    return msgHistory;
}


__gptDialog_getSystemMessage = function (message) {
    return {
        "role": "system",
        "content": message
    }
}


__gptIsValidHtml = function (html) {
    html = html.replace(/<[^>]*\/\s?>/g, '');      // Remove all self closing tags
    html = html.replace(/<(br|hr|img).*?>/g, '');  // Remove all <br>, <hr>, and <img> tags
    var openingTags = html.match(/<[^\/].*?>/g) || [];        // Get remaining opening tags
    var closingTags = html.match(/<\/.+?>/g) || [];           // Get remaining closing tags

    return (openingTags.length === closingTags.length);
}

__gptIsValidXML = function(text) {
    try {
        XML.parseSequential(text);
        return true;
    } catch (e) {
        return false;
    }
}

__gptIsXML = function (input) {
    return /<[^<>]+>/.test(input);
}

__gptIsMarkdown = function (input) {
    return /^#|\*\*/m.test(input);
}

getLastDialogNodeOutputName = function() {
    return __gptFunctionCall;
}

__gptInput = null;
__gptLastDialogMessage = null; // bot, user, action
__gptLastActionResult = null;
__lastMessage = null;
__lastMessages = __gptDialog_getPrevMessages();

//log_debug('History to evaluate: ' + JSON.stringify(__lastMessages));

for (var i = __lastMessages.length-1; i >= 0; i--) {
    __lastMessage = __lastMessages[i];

    if (__lastMessage['role'] == 'function') {
        __gptLastDialogMessage = 'action';
        __gptLastActionResult = __lastMessage['content'];
        break;
    } else if (__lastMessage['role'] == 'user') {
        __gptInput = __lastMessage['content'];
        __gptLastDialogMessage = 'user';
        break;
    } else if (__lastMessage['role'] == 'assistant' && __lastMessage['function_call']) {
        __gptLastDialogMessage = 'action';
        break;
    } else if (__lastMessage['role'] == 'assistant') {
        __gptLastDialogMessage = 'bot';
        break;
    }
}

//log_debug('Last dialog message: ' + __gptLastDialogMessage);

if (__message == '') {
    __message = null;
}
if (__message && __message.length <= 2) {
    __message = null; // this could fix issue whem message contains two apostrohpes -> no valid GPT instruct using just two letters!
}


// validation IF ALL functions and their result are in the history!
var __functionCallCount = 0;
var __functionResultCount = 0;

for (var i = 0; i < __lastMessages.length; i++) {
    if (__lastMessages[i].function_call) __functionCallCount++;
    if (__lastMessages[i].role == "function") __functionResultCount++;
}

var __gptFunctionCallHistoryCount = 0;
for (var i = 0; i < __gptFunctionCallHistory.length; i++) {
    if (__gptFunctionCallHistory[i].componentId == __gptComponentId) {
        __gptFunctionCallHistoryCount++; // count only functions in current Dialog Node
    }
}

var __validFunctionCall = true;
if (__functionCallCount != __functionResultCount) __validFunctionCall = false;
if (__functionCallCount != __gptFunctionCallHistoryCount) __validFunctionCall = false;

if (!__validFunctionCall && __gptDialogHistoryStartFrom == 0) {
    log_warn("The number of action(functions) does not match! Action history count: " + __gptFunctionCallHistoryCount +" (total: " + __gptFunctionCallHistory.length + "), function call count: " + __functionCallCount + ", results found: " + __functionResultCount);
    log_warn(JSON.stringify(__gptFunctionCallHistory));
    log_warn(JSON.stringify(__lastMessages));
}

// evaluate if last result contains HTML or MD
if (__gptLastDialogMessage == "action" && __gptLastActionResult) {
    if (__gptIsXML(__gptLastActionResult)) {
        __gptHTMLorMDused = true;
    } else if (__gptIsMarkdown(__gptLastActionResult)) {
        __gptHTMLorMDused = true;
    }
}

// override __dialogControlOnEntry behavior
if (typeof __gpt_dialogControlOnEntry !== 'undefined' && __gpt_dialogControlOnEntry != null) {
    __dialogControlOnEntry = __gpt_dialogControlOnEntry;
}

if (__resultArrived) return delay(100);

__speak = false; 
__recognize = false; 


request = {
    "model": __gptCurrentModel,
    "split_on": /((?:[^MD]rs?\.|[^Mr]s\.|[^-.:\s]\s+\d+\.|[^\s\d]\d+\.|[^rs\d]\.|[-?!])\s+)[A-Z\n]/,
    "messages": __gptCurrentMessages, 
    /*"temperature": parseFloat(__temperature.toString()), */
    "top_p": 1, 
    "service_host": __gptServiceHost, 
    "frequency_penalty": 0, 
    "presence_penalty": 0,
    "seed": __gptSeed,
    /*"max_tokens": __gptMaxTokens,*/
    "share_connection": true
}

if (__gptModel.indexOf("gpt-5") >= 0) {
    request["max_completion_tokens"] = __gptMaxTokens;
} else {
    request["max_tokens"] = __gptMaxTokens;
    request["temperature"] = parseFloat(__temperature.toString());
}




request.functions = null;
if (__gptIntents && __confirmIntentMode == 0 && (__sayInstruction == null || __sayInstruction.length == 0)) {
    if (__gptFunctionsDefinition != null && __gptFunctionsDefinition.length == 0) {
        request.functions = null;
    } else {
        request.functions = __gptFunctionsDefinition;
    }
}

__confirmIntentMode = 0; //clear FLAG for confirmation request


__lastGptRequest = request.messages; 


if (__gptLogCounter == 0 && __logPrompt) {
    __gptLogCounter++;
    log_debug("GPT request: " + JSON.stringify(request)); 
} 

if (!__streamRequest) { 
    __streamRequest = gptRequest("chat/completions", request);

    // start - 15*200 ms for response
    if (typeof Task === "undefined") {
        // start - 15*200 ms for response
        __streamWaitAttempts = 15;
    }
} 

if (__streamWaitAttempts === 15 || __streamWaitAttempts === null) {
    // at first or during repeat continue
    __streamRequest.then( 
        function (result) { 
            __gptRequestEnd = new Date();
            __gptRequestTTFT = __gptRequestEnd - __gptRequestStart; // time to first token

            __streamWaitAttempts = null; // wait signal for next response
            __resultArrived = true;

            if (__logPrompt) {
                log_debug("GPT response (" + __gptRequestTTFT+"ms):" + JSON.stringify(result)); 
            }

            __streamRequest = null; 

            if (result.success) {
                __requestCounter = 0; 

                if (!result.response || result.response == "[DONE]") { 
                    __recognize = true; 

                    /* __speak is false, so we can disable VAD immediatelly */
                    if (__gptDialogVADEnabled) {
                        stopVoiceDetection();
                    }

                    return; 
                } 


                if (result.response.choices && result.response.choices.length > 0 && result.response.choices[0].message.function_call) {

                    __gptFunctionCall = result.response.choices[0].message.function_call.name;
                    __gptFunctionObject = result.response.choices[0].message.function_call;

                    return;
                }

                __streamRequest = result.next;

                if (!result.response.choices || result.response.choices.length == 0) {
                    return; 
                } 

                var message = result.response.choices[0].message; 

                if (typeof message.content === 'undefined') { 
                    message.content = null; 
                } 

                if (!!message.content) { 
                    __gptOutput = message.content; 
                    __gptInput = ""; 
                    __recognize = false; 
                    __speak = true;

                    if (__gptOutput.indexOf("```") >= 0 ||
                        __gptOutput.indexOf("`function") >= 0 ||
                        __gptOutput.indexOf("`typescript") >= 0 ||
                        (__gptOutput.indexOf("{") >= 0 && __gptOutput.indexOf("\"")) ||
                        (__gptOutput.indexOf("{") >= 0 && __gptOutput.indexOf("'")) ||
                        __gptOutput.indexOf("Calling function") >= 0) {
                            if (__logPrompt) { log_warn("GPT code output instead of function call. Output skipped. Content: " + __gptOutput); }
                            __gptOutput = ""; /* output contains code */
                    }
                }
            } else {
                __requestCounter++;  
                __gptOutput = __gptDialog_getRepeatMessage(); // when failure, we ask client to repeat to have some time
            } 
        } 
    ); 
}

if (typeof Task !== "undefined") {

    if (__gptCurrentWaitDelay == null) {
        __gptCurrentWaitDelay = __gptShortWaitDelay;
    } else {
        __gptCurrentWaitDelay = __gptLongWaitDelay;
    }

    if (__streamRequest) {
        return Task.timeout(__gptCurrentWaitDelay, __streamRequest, "timeout").then(result => {
            if (result !== "timeout") __resultArrived = true;
        });
    } else {
        return;
    }

}

