            __gptFunctionCall = null;
            for (var i = 0; i < __componentOutputRelationConfig.length; i++) {

                if (!__componentOutputRelationConfig[i].Name) continue; /* skip no_input because its not an intent */

                if (transformFunctionName(__gptFunctionCallArgs["intent_id"]) == transformFunctionName(__componentOutputRelationConfig[i].Name)) {
                    __gptFunctionCall = __componentOutputRelationConfig[i].Name;
                    break;
                }
            }

            if (__gptFunctionCall == null) {
                log_warn("Intent mode error! Intent ID does not match output relation name in Dialog Node. Detected intent: " + JSON.stringify(__gptFunctionCallArgs));
            } else {
                if (__logPrompt) {
                    log_debug("Intent successfully injected: " + __gptFunctionCall);
                }
            }
        } else {
            log_warn("Intent mode error! Arguments does not contains intent Id: " + JSON.stringify(__gptFunctionCallArgs));
            __gptFunctionCall = null;
        }
    }
}

