        //log_debug(__componentOutputRelationConfig[i].Name);

        if (__componentOutputRelationConfig[i].ApplyWhen == true) {
            //log_debug("true, gpt func is: " + __gptFunctionCall);

            if (transformFunctionName(__componentOutputRelationConfig[i].Name) == transformFunctionName(__gptFunctionCall)) {

                //log_debug("Name matches function!");

                __validOutput = true; 
                __outputRelation = __componentOutputRelationConfig[i].label;

                __gptOutputConfirmation[__componentOutputRelationConfig[i].Name]++; // output counter - used for explicit confirmation
                if (__gptOutputConfirmation[__componentOutputRelationConfig[i].Name] == 1) {

                    if (__componentOutputRelationConfig[i].Confirmation == 'Explicit') {
                        __confirmIntentMode = 1;
                    }

                    if (__componentOutputRelationConfig[i].Confirmation == 'Implicit') {
                        __confirmIntentMode = 2;
                    }

                    if (__componentOutputRelationConfig[i].Confirmation == 'Auto') {
